<?php require_once __DIR__.'/../includes/functions.php';require_role('admin');$rows=$pdo->query('SELECT a.attendance_date,s.admission_number,CONCAT(s.first_name," ",s.last_name) student_name,a.status FROM attendance a JOIN students s ON s.id=a.student_id ORDER BY a.attendance_date DESC LIMIT 100')->fetchAll();$pageTitle='Attendance';$base='../';require __DIR__.'/../includes/header.php';?><div class='layout'><?php require __DIR__.'/../includes/sidebar.php';?><section class='content'><div class='card'><h1>Attendance</h1><div class='table-wrap'><table class='table'><?php if($rows):?><tr><?php foreach(array_keys($rows[0]) as $h):?><th><?=e(ucwords(str_replace('_',' ',$h)))?></th><?php endforeach;?></tr><?php foreach($rows as $r):?><tr><?php foreach($r as $v):?><td><?=e((string)$v)?></td><?php endforeach;?></tr><?php endforeach;?><?php endif;?></table></div></div></section></div><?php require __DIR__.'/../includes/footer.php';?>